5	namespace App\Inventory\Application\EventHandler;
6	
7	use App\Inventory\Domain\Repository\StockItemRepository;
8	use App\Ordering\Domain\Event\OrderCancelled;
9	use Symfony\Component\Messenger\Attribute\AsMessageHandler;
10	
11	/**
12	 * Stornovaná objednávka uvolní všechny své rezervace.
13	 */
14	#[AsMessageHandler(bus: 'event.bus')]
15	final readonly class ReleaseReservationsHandler
16	{
17	    public function __construct(
18	        private StockItemRepository $stockItems,
19	    ) {}
20	
21	    public function __invoke(OrderCancelled $event): void
22	    {
23	        foreach ($this->stockItems->reservedFor($event->orderId) as $stockItem) {
24	            $stockItem->release($event->orderId);
25	            $this->stockItems->save($stockItem);
26	        }
27	    }
28	}
