5	namespace App\Ordering\Infrastructure\Repository;
6	
7	use App\Ordering\Domain\Exception\OrderNotFoundException;
8	use App\Ordering\Domain\Model\Order;
9	use App\Ordering\Domain\Repository\OrderRepository;
10	use App\Ordering\Domain\ValueObject\CustomerId;
11	use App\Ordering\Domain\ValueObject\OrderId;
12	use Doctrine\ORM\EntityManagerInterface;
13	use Symfony\Component\DependencyInjection\Attribute\Target;
14	use Symfony\Component\Messenger\MessageBusInterface;
15	
16	final readonly class DoctrineOrderRepository implements OrderRepository
17	{
18	    public function __construct(
19	        private EntityManagerInterface $entityManager,
20	        #[Target('event.bus')]
21	        private MessageBusInterface $eventBus,
22	    ) {}
23	
24	    public function get(OrderId $id): Order
25	    {
26	        return $this->find($id) ?? throw OrderNotFoundException::withId($id);
27	    }
28	
29	    public function find(OrderId $id): ?Order
30	    {
31	        return $this->entityManager->find(Order::class, $id);
32	    }
33	
34	    public function findByCustomer(CustomerId $customerId): array
35	    {
36	        /** @var list<Order> */
37	        return $this->entityManager->createQueryBuilder()
38	            ->select('o')
39	            ->from(Order::class, 'o')
40	            ->where('o.customerId = :customerId')
41	            ->orderBy('o.placedAt', 'DESC')
42	            ->setParameter('customerId', $customerId->value)
43	            ->getQuery()
44	            ->getResult();
45	    }
46	
47	    public function findByStatus(string $status): array
48	    {
49	        /** @var list<Order> */
50	        return $this->entityManager
51	            ->createQuery('SELECT o FROM App\Ordering\Domain\Model\Order o WHERE o.status = :status ORDER BY o.placedAt DESC')
52	            ->setParameter('status', $status)
53	            ->getResult();
54	    }
55	
56	    public function save(Order $order): void
57	    {
58	        $this->entityManager->persist($order);
59	        $this->entityManager->flush();
60	
61	        // Události se publikují až po uložení agregátu.
62	        foreach ($order->releaseEvents() as $event) {
63	            $this->eventBus->dispatch($event);
64	        }
65	    }
66	}
